import React, { useState, useEffect, useRef } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

// Simulate the list of available OBJ models
const modelList = [
  { name: 'Model1', path: './stls/model1.obj' },
  { name: 'Model2', path: './stls/model2.obj' },
  { name: 'Model3', path: './stls/model3.obj' },
  // Add other models here
];

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);
  const groupRef = useRef(null);
  const { camera } = useThree();

  useEffect(() => {
    const loader = new OBJLoader();
    loader.load(
      modelPath,
      (obj) => {
        // Calculate the bounding box to understand model size
        const box = new THREE.Box3().setFromObject(obj);
        const size = box.getSize(new THREE.Vector3());
        const maxDimension = Math.max(size.x, size.y, size.z);
        obj.rotation.x = -Math.PI / 2;
        // Scale the model proportionally
        const scaleFactor = 2.5 / maxDimension;

        obj.scale.set(scaleFactor, scaleFactor, scaleFactor);

        // Center the model
        box.setFromObject(obj);
        const center = box.getCenter(new THREE.Vector3());
        obj.position.sub(center);

        // Replace meshes with visible edge lines
        obj.traverse((child) => {
          if (child.isMesh) {
            // Create edges geometry
            const edges = new THREE.EdgesGeometry(child.geometry, 45);
            const lineMaterial = new THREE.LineBasicMaterial({
              color: 0xffffff,
              opacity: 0.5,
              transparent: true
            });
            const edgeLines = new THREE.LineSegments(edges, lineMaterial);

            // Copy transformations from the original mesh
            edgeLines.position.copy(child.position);
            edgeLines.rotation.copy(child.rotation);
            edgeLines.scale.copy(child.scale);

            // Replace the original mesh with edge lines
            child.parent.add(edgeLines);
            child.parent.remove(child);
          }
        });

        // If groupRef exists, add the model to it
        if (groupRef.current) {
          groupRef.current.add(obj);
        }
        setModel(obj);
      },
      undefined,
      (error) => {
        console.error('Error loading OBJ:', error);
      }
    );
  }, [modelPath]);

  // Rotate around the center
  useFrame(() => {
    if (groupRef.current) {
      groupRef.current.rotation.y += 0.003;
    }
  });

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
    </group>
  );
};

const App = () => {
  const [selectedModel, setSelectedModel] = useState(modelList[0]);
  const [highlightedIndex, setHighlightedIndex] = useState(0);
  const modelPath = selectedModel.path;

  const handleKeyPress = (event) => {
    if (event.key === 'ArrowDown') {
      setHighlightedIndex((prevIndex) => (prevIndex + 1) % modelList.length);
    } else if (event.key === 'ArrowUp') {
      setHighlightedIndex((prevIndex) => (prevIndex - 1 + modelList.length) % modelList.length);
    }
  };

  const handleModelClick = (index) => {
    setHighlightedIndex(index);
    setSelectedModel(modelList[index]);
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyPress);
    return () => {
      window.removeEventListener('keydown', handleKeyPress);
    };
  }, []);

  return (
    <div style={{ display: 'flex' }}>
      {/* Left Panel with List of Models */}
      <div
        style={{
          width: '200px',
          backgroundColor: '#222',
          color: 'white',
          padding: '10px',
          fontFamily: 'Courier New',
          height: '100vh',
          overflowY: 'auto',
        }}
      >
        <h2>Select Model</h2>
        {modelList.map((model, index) => (
          <div
            key={model.name}
            onClick={() => handleModelClick(index)}
            style={{
              padding: '10px',
              cursor: 'pointer',
              backgroundColor: highlightedIndex === index ? '#444' : 'transparent',
            }}
          >
            {model.name}
          </div>
        ))}
      </div>

      {/* 3D Canvas */}
      <div style={{ flex: 1, height: '100vh', position: 'relative' }}>
        <h1
          style={{
            transform: 'scale(0.5)',
            position: 'absolute',
            color: 'white',
            top: '10px',
            left: '10px',
            zIndex: 10,
            fontFamily: 'Courier New',
          }}
        >
          <h1>Welcome to AII3.org</h1>
          <h2>This Website is Under Construction</h2>
          <h2>Email: parz@aii3.org</h2>
          <h2>blog: parz.wiki</h2>
        </h1>

        <Canvas
          style={{ backgroundColor: 'black' }}
          camera={{
            position: [2.5, 2.5, 2.5],
            fov: 45,
          }}
        >
          {/* Lights */}
          <ambientLight intensity={0.5} />
          <spotLight position={[10, 10, 10]} intensity={1} />
          <directionalLight position={[5, 5, 5]} intensity={1} />

          {/* Model loader */}
          <ModelLoader modelPath={modelPath} />

          {/* Orbit controls with limited rotation and no zoom */}
          <OrbitControls
            enableZoom={false}
            minPolarAngle={Math.PI / 4}
            maxPolarAngle={Math.PI / 4}
            minAzimuthAngle={-Math.PI / 4}
            maxAzimuthAngle={Math.PI / 4}
          />
        </Canvas>
      </div>
    </div>
  );
};

export default App;
